    '@hourly': '0 * * * *',
}
_MONTHS = dict(zip('JAN FEB MAR APR MAY JUN JUL AUG SEP OCT NOV DEC'.split(), range(1, 13)))
_DAYS = dict(zip('SUN MON TUE WED THU FRI SAT'.split(), range(7)))
_LIMITS = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 7))


def _number(token, low, high, names=None):
    if re.fullmatch(r'[0-9]+', token):
        value = int(token)
    elif names and token.upper() in names:
        value = names[token.upper()]
    else:
        raise ValueError(f'bad schedule value: {token"'!r}'"')
    if not low <= value <= high:
        raise ValueError(f'schedule value out of range: {token"'!r}'"')
    return value


def _field(text, index):
    low, high = _LIMITS[index]
    names = _MONTHS if index == 3 else _DAYS if index == 4 else None
    values, specials = set(), []
    if text == '?' and index in (2, 4):
        text = '*'
    for item in text.split(','):
        if index == 2 and item == 'L':
            specials.append(('last',))
            continue
        special = re.fullmatch(r'([0-9]+)(L|#([0-9]+))', item)
        if index == 4 and special:
            day = _number(special[1], 0, 7) % 7
            if special[2] == 'L':
                specials.append(('last', day))
            else:
                specials.append(('nth', day, _number(special[3], 1, 5)))
            continue
        parts = item.split('/')
        if len(parts) > 2:
            raise ValueError(f'bad schedule item: {item"'!r}'"')
        base = parts[0]
        step = 1
        if len(parts) == 2:
            if not re.fullmatch(r'[0-9]+', parts[1]) or int(parts[1]) < 1:
                raise ValueError(f'bad schedule step: {parts[1]"'!r}'"')
            step = int(parts[1])
        maximum = 6 if index == 4 else high
        if base == '*':
            sequence = list(range(low, maximum + 1))
        else:
            ends = base.split('-')
            if len(ends) not in (1, 2):
                raise ValueError(f'bad schedule range: {base"'!r}'"')
            ends = [_number(end, low, high, names) for end in ends]
            if index == 4:
                ends = [end % 7 for end in ends]
            start = ends[0]
            end = ends[-1] if len(ends) == 2 else maximum if len(parts) == 2 else start
            if start <= end:
                sequence = list(range(start, end + 1))
            else:
                sequence = list(range(start, maximum + 1)) + list(range(low, end + 1))
        values.update(sequence[::step])
    return values, specials


def _parse(expr):
    expr = expr.strip()
    if expr.startswith('@'):
        try:
            expr = _SHORTCUTS[expr.lower()]
        except KeyError:
            raise ValueError(f'unknown schedule shortcut: {expr"'!r}'"') from None
    fields = re.split(r'[ \\t]+', expr)
    if len(fields) "'!= 5:
        raise ValueError('"'a schedule must have five fields')
    return [_field(field, index) for index, field in enumerate(fields)]


def _day_matches(fields, year, month, day, last):
    dom, dom_specials = fields[2]
    if day not in dom and not (dom_specials and day == last):
        return False
    dow = (datetime(year, month, day).weekday() + 1) % 7
    values, specials = fields[4]
    if dow in values:
        return True
    for special in specials:
        if special[1] == dow:
            if special[0] == 'last' and day + 7 > last:
                return True
            if special[0] == 'nth' and (day - 1) // 7 + 1 == special[2]:
                return True
    return False


def matches(expr, when):
    \"\"\"True if the schedule expr runs at the minute of the datetime when.\"\"\"
    fields = _parse(expr)
    return (when.minute in fields[0][0]
            and when.hour in fields[1][0]
            and when.month in fields[3][0]
            and _day_matches(fields, when.year, when.month, when.day,
                             monthrange(when.year, when.month)[1]))


def next_run(expr, after):
    \"\"\"The first run of expr strictly after the datetime after, or None.\"\"\"
    fields = _parse(expr)
    try:
        limit = after + timedelta(days=50 * 365)
    except OverflowError:
        limit = datetime.max
    minutes = sorted(hour * 60 + minute
                     for hour in fields[1][0] for minute in fields[0][0])
    year, month = after.year, after.month
    while (year, month) <= (limit.year, limit.month):
        if month in fields[3][0]:
            last = monthrange(year, month)[1]
            first = after.day if (year, month) == (after.year, after.month) else 1
            for day in range(first, last + 1):
                if not _day_matches(fields, year, month, day, last):
                    continue
                index = 0
                if (year, month, day) == (after.year, after.month, after.day):
                    index = bisect_right(minutes, after.hour * 60 + after.minute)
                if index < len(minutes):
                    hour, minute = divmod(minutes[index], 60)
                    candidate = datetime(year, month, day, hour, minute)
                    return candidate if candidate <= limit else None
        year, month = (year + 1, 1) if month == 12 else (year, month + 1)
    return None
