from tally import schedule, allocate, duration, fields, intervals, ledger
from datetime import datetime, timedelta
from fractions import Fraction
from time import perf_counter
assert allocate.allocate_units(-5,[1,1,1]) == [-2,-2,-1]
assert allocate.allocate_units(7,[Fraction(1,3),Fraction(2,3)]) == [2,5]
for text in ['', '1m1h','1h1h','1h junk','1 h','-2s']:
    try: duration.parse(text)
    except ValueError: pass
    else: raise AssertionError(text)
assert duration.parse(' 2H 5m ') == 7500
assert fields.parse_fields(\"a='  it''s|ok=x  '|b= |\") == {'a': \"  it's|ok=x  \", 'b': ''}
for text in [\"a='oops\",'a=1|a=2']:
    try: fields.parse_fields(text)
    except ValueError: pass
    else: raise AssertionError(text)
assert intervals.merge([(4,8),(1,4),(3,3)]) == [(1,8)]
assert intervals.free_slots([(-5,2),(8,20)],0,10) == [(2,8)]
assert ledger.bill([(' A ','1s'),('a','1s'),('B','1s')],1800) == [('A',1),('B',1)]
assert ledger.bill([('A','0s')],100) == [('A',0)]
for expr in ['* * * * *','*/7 22-2 * * FRI-MON','0 0 L * *','0 0 * * 5L','0 0 * * 1#2','0 0 * * 0-7','0 0 * * 5/2']:
    start = datetime(2026,5,1,23,59,15)
    actual = schedule.next_run(expr,start)
    brute = start.replace(second=0) + timedelta(minutes=1)
    while not schedule.matches(expr,brute): brute += timedelta(minutes=1)
    assert actual == brute, (expr, actual, brute)
for expr in ['60 * * * *','* * * * ?', '* * ? * *']:
    if '60' not in expr: continue
    try: schedule.matches(expr,None)
    except ValueError: pass
    else: raise AssertionError(expr)
for expr in ['* * * *','* * * * * *','*/0 * * * *','* * *, * *','* * * ? *','* * * * MON#2','* * L/2 * *','* * * * 8L','* * * * 1#6','* * * * 1/Jan','*\\n* * * *','@unknown']:
    try: schedule.next_run(expr,None)
    except ValueError: pass
    else: raise AssertionError(expr)
t = perf_counter()
assert schedule.next_run('0 0 31 2 *',datetime(2026,1,1)) is None
print('Additional edge checks passed; impossible schedule took',perf_counter()-t,'seconds')
